// Reads the incoming email and skips anything that should not get an automatic reply
const MY_EMAIL = 'contato@vidaltechnologies.com.br';
const out = [];

for (const item of $input.all()) {
  const e = item.json;

  // Sender: accepts a string ("Name <email>") or an object
  const fromText = typeof e.from === 'string' ? e.from : (e.from?.text || e.from?.value?.[0]?.address || '');
  const match = fromText.match(/<([^>]+)>/);
  const email = (match ? match[1] : fromText).trim().toLowerCase();
  const name = (match ? fromText.replace(/<[^>]+>/, '') : '').replace(/"/g, '').trim();

  // Never reply to ourselves, to bots or to auto-replies
  const isBot = /no-?reply|mailer-daemon|postmaster|notifica|newsletter/i.test(email);
  const subject = (e.subject || '').trim();
  const isAutoReply = /^(auto|resposta autom|automatic reply|out of office|fuera de la oficina)/i.test(subject);
  if (!email || email === MY_EMAIL || isBot || isAutoReply) continue;

  // Only the FIRST contact gets an automatic reply.
  // Replies inside a conversation (Re:, RES:, RV:...) are left for a human.
  const isThreadReply = !!(e.inReplyTo || e.references) || /^(re|res|rv|fw|fwd|enc|aw|tr)\s*:/i.test(subject);
  if (isThreadReply) continue;

  // Email body (strips HTML and trims very long messages)
  let body = e.textPlain || e.text || '';
  if (!body && (e.textHtml || e.html)) {
    body = String(e.textHtml || e.html).replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ');
  }
  body = body.replace(/\s+\n/g, '\n').replace(/[ \t]+/g, ' ').trim().slice(0, 4000);

  out.push({ json: { sender_email: email, sender_name: name, subject, message: body } });
}

return out;

// Matches each email against the Supabase "customers" table
// Customers with welcome_sent = true get nothing (a human replies)
const emails = $('Read and filter email').all();
const rows = $input.all().map((i) => i.json).filter((r) => r && r.email);

const out = [];
for (const e of emails) {
  const customer = rows.find((r) => String(r.email).toLowerCase() === e.json.sender_email);
  if (customer && customer.welcome_sent === true) continue;
  out.push({ json: {
    ...e.json,
    customer_exists: !!customer,
    customer_id: customer ? customer.id : null,
  } });
}
return out;

// Combines the AI answer with the email data and builds the final branded email
const SITE = 'https://vidaltechnologies.com.br';
const CATALOGS = {
  pt: SITE + '/catalogo/vidal-technologies-apresentacao.pdf',
  en: SITE + '/catalogo/vidal-technologies-presentation-en.pdf',
  es: SITE + '/catalogo/vidal-technologies-presentacion-es.pdf',
};
const SIGNATURE = {
  pt: { team: 'Equipe Vidal Technologies', whatsapp: 'Falar no WhatsApp', attachment: 'Segue em anexo o nosso catálogo de serviços.' },
  en: { team: 'Vidal Technologies Team', whatsapp: 'Chat on WhatsApp', attachment: 'Our service catalog is attached.' },
  es: { team: 'Equipo Vidal Technologies', whatsapp: 'Hablar por WhatsApp', attachment: 'Adjuntamos nuestro catálogo de servicios.' },
};
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const original = $('Check customer status').all()[i].json;
  let raw = String(items[i].json.text || items[i].json.output || '').replace(/```json|```/g, '').trim();
  let ai;
  try {
    ai = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
  } catch (err) {
    continue; // if the AI returns something unexpected, send nothing
  }
  if (!ai.should_reply || !ai.reply_text) continue; // spam, ads, etc.

  const language = ['pt', 'en', 'es'].includes(ai.language) ? ai.language : 'pt';
  const s = SIGNATURE[language];
  const sendCatalog = ai.send_catalog === true;
  const paragraphs = String(ai.reply_text).split(/\n{1,}/).filter(Boolean)
    .map((p) => `<p style="margin:0 0 14px">${esc(p)}</p>`).join('');

  const html = `
<div style="background:#f4f4f4;padding:24px 0;font-family:Arial,Helvetica,sans-serif">
  <div style="max-width:600px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden">
    <div style="background-color:#000000;background-image:linear-gradient(#000000,#000000);padding:18px 28px">
      <img src="${SITE}/catalogo/logo-email.png" width="230" height="45" alt="Vidal Technologies" style="display:block;border:0;outline:none;text-decoration:none">
    </div>
    <div style="padding:28px;color:#1a1a1a;font-size:15px;line-height:1.6">
      ${paragraphs}
      ${sendCatalog ? `<p style="margin:0 0 14px"><b>${s.attachment}</b></p>` : ''}
      <p style="margin:24px 0 0">${s.team}</p>
      <p style="margin:18px 0 0">
        <a href="https://wa.me/5541988779179" style="background:#FBC105;color:#000;text-decoration:none;padding:10px 20px;border-radius:999px;font-weight:bold;display:inline-block">${s.whatsapp}</a>
      </p>
    </div>
    <div style="background-color:#111111;background-image:linear-gradient(#111111,#111111);color:#9a9a9a;padding:16px 28px;font-size:12px">
      <a href="${SITE}" style="color:#FBC105;text-decoration:none">vidaltechnologies.com.br</a> · contato@vidaltechnologies.com.br
    </div>
  </div>
</div>`;

  const subject = original.subject ? (/^re:/i.test(original.subject) ? original.subject : 'Re: ' + original.subject) : 'Vidal Technologies';

  out.push({ json: {
    to: original.sender_email,
    name: original.sender_name || original.sender_email.split('@')[0],
    customer_exists: original.customer_exists,
    customer_id: original.customer_id,
    subject,
    html,
    language,
    category: ai.category || 'other',
    send_catalog: sendCatalog,
    catalog_url: CATALOGS[language],
  } });
}
return out;
